# Look for label data more carefully
print("Lines 80-89 (end of context):")
for i in range(80, len(lines)):
    print(f"{i}: {lines[i][:200]}")

# Search for "Label:" more specifically
print("\nSearching for 'Label:' in context:")
for i, line in enumerate(lines):
    if 'Label:' in line:
        print(f"Line {i}: {line[:200]}")

# Find all lines with February dates
february_lines = []
for i, line in enumerate(lines):
    if 'Date: Feb' in line or 'Date: February' in line:
        february_lines.append((i, line))

print(f"Found {len(february_lines)} February instances:")
for idx, (line_num, line) in enumerate(february_lines):
    print(f"{idx+1}. Line {line_num}: {line[:150]}")
